from fractions import Fraction as F
rows=[('A',13,[1,0,0,0]),('A',3,[0,0,0,1]),('B',9,[1,0,1,0]),('B',5,[0,0,1,1]),('C',5,[1,1,1,0]),('C',8,[0,0,1,0]),('D',6,[1,0,0,0]),('D',5,[0,0,1,1])]
tests='TUVW'; modes='ABCD'
cost=list(map(F,['1.8','1.5','1.2','0.8']))
loss=[[0,11,6,16],[22,0,20,8],[16,23,0,7],[18,11,20,0]]
def solve(ids,available,k):
    total=sum(rows[i][1] for i in ids)
    opts=[(sum(F(rows[i][1],total)*loss[a][modes.index(rows[i][0])] for i in ids),modes[a]) for a in range(4)]
    if k:
        for t in available:
            val=cost[t]
            for b in [0,1]:
                sub=[i for i in ids if rows[i][2][t]==b]
                if sub:
                    val+=F(sum(rows[i][1] for i in sub),total)*solve(sub,[j for j in available if j!=t],k-1)[0]
            opts.append((val,tests[t]))
    return min(opts)
ids=list(range(8)); total=sum(r[1] for r in rows)
first_losses={'STOP':float(solve(ids,[],0)[0])}
for t in range(4):
    val=cost[t]
    for b in [0,1]:
        sub=[i for i in ids if rows[i][2][t]==b]
        if sub: val+=F(sum(rows[i][1] for i in sub),total)*solve(sub,[j for j in range(4) if j!=t],1)[0]
    first_losses[tests[t]]=float(val)
best=solve(ids,list(range(4)),2)
print('best',best[1],float(best[0]))
print(first_losses)
if best[1] in tests:
    t=tests.index(best[1])
    print({str(b):solve([i for i in ids if rows[i][2][t]==b],[j for j in range(4) if j!=t],1)[1] for b in [0,1]})

